    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'Which of the following is the most appropriate induction agent for rapid sequence intubation (RSI) in a patient with a severe asthma exacerbation and normal blood pressure?', '["Propofol", "Etomidate", "Ketamine", "Midazolam"]', 2, 'Ketamine is a dissociative anesthetic that provides bronchodilation due to its sympathomimetic properties, making it ideal for severe asthma exacerbations.'),
    (v_topic_id, 'A trauma patient requires emergency intubation. They are hypotensive (BP 70/40) with suspected internal bleeding. Which induction agent is most hemodynamically stable?', '["Propofol", "Ketamine", "Etomidate", "Thiopental"]', 2, 'Etomidate is highly cardiostable and is often preferred for induction in hypotensive or hemodynamically unstable trauma patients. Ketamine is also an option but can cause a negative inotropic effect in catecholamine-depleted patients.'),
    (v_topic_id, 'Which of the following is a classic side effect of Etomidate administration that limits its use as a continuous infusion?', '["Transient adrenal suppression", "Bronchospasm", "Malignant hyperthermia", "Hyperkalemia"]', 0, 'Etomidate inhibits 11-beta-hydroxylase, leading to a dose-dependent, transient suppression of cortisol and aldosterone synthesis.'),
    (v_topic_id, 'Succinylcholine is contraindicated in a patient presenting 5 days after a massive crush injury due to the risk of:', '["Malignant hyperthermia", "Severe hyperkalemia", "Histamine release causing hypotension", "Prolonged apnea due to pseudocholinesterase deficiency"]', 1, 'In severe crush injuries, burns, or denervation injuries (after 48-72 hours), upregulation of extrajunctional acetylcholine receptors occurs. Succinylcholine can cause a massive, life-threatening efflux of potassium.'),
    (v_topic_id, 'What is the standard reversal agent for profound neuromuscular blockade induced by Rocuronium?', '["Neostigmine", "Sugammadex", "Flumazenil", "Atropine"]', 1, 'Sugammadex rapidly and selectively encapsulates and inactivates rocuronium and vecuronium, allowing for rapid reversal of neuromuscular blockade.'),
    (v_topic_id, 'The "L" in the LEMON mnemonic for difficult airway assessment stands for:', '["Laryngoscopy view", "Look externally", "Lung sounds", "Lateral neck mobility"]', 1, 'LEMON: Look externally, Evaluate (3-3-2), Mallampati score, Obstruction, Neck mobility.'),
    (v_topic_id, 'During airway assessment, a Mallampati Class III airway is defined by visualization of:', '["Only the hard palate", "The hard palate, soft palate, and base of the uvula", "The hard palate, soft palate, fauces, and entire uvula", "The hard palate and soft palate only"]', 1, 'Class I: Entire uvula. Class II: Tip of uvula obscured. Class III: Base of uvula visible. Class IV: Only hard palate visible.'),
    (v_topic_id, 'According to the 3-3-2 rule for difficult airway evaluation, the first "3" assesses the distance between the:', '["Hyoid bone and thyroid cartilage", "Mentum and hyoid bone", "Patient''s upper and lower teeth (mouth opening)", "Thyroid notch and cricoid ring"]', 2, 'The 3-3-2 rule evaluates mouth opening (3 fingers), thyromental distance (3 fingers), and thyrohyoid distance (2 fingers).'),
    (v_topic_id, 'Which maneuver involves applying backward, upward, rightward, and posterior pressure to the thyroid cartilage to improve glottic visualization?', '["Sellick maneuver", "BURP maneuver", "Jaw-thrust maneuver", "Sniffing position"]', 1, 'The BURP maneuver shifts the larynx to bring the glottic opening into the line of sight during direct laryngoscopy. The Sellick maneuver is cricoid pressure to prevent aspiration.'),
    (v_topic_id, 'The primary goal of preoxygenation (denitrogenation) prior to rapid sequence intubation is to:', '["Prevent bradycardia", "Maximize safe apnea time before desaturation occurs", "Decrease the required dose of induction agents", "Prevent hypercapnia during the procedure"]', 1, 'Replacing nitrogen in the functional residual capacity (FRC) with oxygen provides a reservoir that significantly delays the onset of hypoxemia during apnea.'),
    (v_topic_id, 'Apneic oxygenation during the period of paralysis and before intubation is best achieved using:', '["A non-rebreather mask at 15 L/min", "A standard nasal cannula at 15 L/min", "Positive pressure ventilation with a bag-valve-mask", "A simple face mask at 10 L/min"]', 1, 'High-flow nasal cannula at 15 L/min during apnea takes advantage of the continuous bulk flow of oxygen into the lungs created by the absorption of oxygen into the blood.'),
    (v_topic_id, 'When using a Macintosh curved laryngoscope blade, the tip should be placed:', '["Directly under the epiglottis to lift it", "In the vallecula to indirectly lift the epiglottis", "Past the vocal cords to guide the tube", "On the posterior pharyngeal wall"]', 1, 'The Macintosh (curved) blade is designed to rest in the vallecula. Tension on the hyoepiglottic ligament indirectly lifts the epiglottis.'),
    (v_topic_id, 'The Miller straight laryngoscope blade is particularly useful in which patient population due to their floppy epiglottis?', '["Elderly patients", "Obese adults", "Pediatric patients", "Pregnant women"]', 2, 'The Miller blade is designed to directly lift the epiglottis, which is highly effective in infants and children who have a relatively large, floppy, and "omega-shaped" epiglottis.'),
    (v_topic_id, 'What is the absolute gold standard for confirming proper endotracheal tube placement in the trachea?', '["Bilateral breath sounds on auscultation", "Condensation in the endotracheal tube", "Continuous waveform capnography (end-tidal CO2)", "Chest X-ray showing the tube above the carina"]', 2, 'While all are helpful, continuous waveform capnography (ETCO2) is the most reliable and objective method to confirm tracheal placement and ventilation.'),
    (v_topic_id, 'Immediately after intubating a patient, you auscultate breath sounds and note they are present on the right but absent on the left. The most likely cause is:', '["Esophageal intubation", "Right mainstem bronchus intubation", "Tension pneumothorax", "Bilateral vocal cord paralysis"]', 1, 'The right mainstem bronchus is wider, shorter, and more vertical than the left. If the ET tube is advanced too far, it typically enters the right mainstem, preventing ventilation of the left lung.'),
    (v_topic_id, 'The DOPE mnemonic is used to troubleshoot a sudden deterioration in an intubated patient. What does the "O" stand for?', '["Oxygen failure", "Obstruction of the tube", "Over-ventilation", "Opiate overdose"]', 1, 'DOPE: Displacement (of the tube), Obstruction (secretions, kinking), Pneumothorax, Equipment failure (ventilator disconnect, oxygen supply).'),
    (v_topic_id, 'In an adult male, what is the appropriate target depth marking (in cm) for an endotracheal tube at the teeth?', '["18-20 cm", "21-23 cm", "25-27 cm", "14-16 cm"]', 1, 'A standard depth is roughly 21-23 cm for adult males and 20-22 cm for adult females, though it varies slightly by patient height.'),
    (v_topic_id, 'Which of the following describes a Grade 3 Cormack-Lehane view during direct laryngoscopy?', '["Full view of the glottis", "Partial view of the glottis and arytenoids", "Only the epiglottis is visible", "Neither the glottis nor the epiglottis is visible"]', 2, 'Grade 1: Full glottis. Grade 2: Partial glottis/arytenoids. Grade 3: Epiglottis only. Grade 4: Soft palate only (no epiglottis).'),
    (v_topic_id, 'In the setting of a Grade 3 Cormack-Lehane view, which adjunct is most likely to facilitate successful intubation?', '["Laryngeal Mask Airway (LMA)", "Gum elastic bougie (Eschmann introducer)", "Nasopharyngeal airway", "Increasing the dose of rocuronium"]', 1, 'A bougie can be blindly directed behind the epiglottis. Proper tracheal placement is confirmed by feeling "tracheal clicks" as the tip runs over the tracheal rings.'),
    (v_topic_id, 'When using a gum elastic bougie, what tactile feedback confirms it has entered the trachea rather than the esophagus?', '["Resistance immediately past the vocal cords", "Feeling rhythmic tracheal ring clicks and hold-up at the carina", "A smooth, frictionless passage", "Inability to advance it past 10 cm"]', 1, 'The angled tip of the bougie bouncing against the cartilaginous tracheal rings creates "clicks," and it will eventually meet resistance ("hold-up") when it reaches the smaller bronchi.'),
    (v_topic_id, 'What is the primary limitation of a Laryngeal Mask Airway (LMA) in an emergency airway scenario?', '["It requires neuromuscular blockade for insertion", "It does not provide a definitive, secure airway against aspiration", "It cannot be connected to standard bag-valve-masks", "It is contraindicated in pediatric patients"]', 1, 'An LMA is a supraglottic rescue airway that sits above the glottis. It does not definitively protect the lungs from aspiration of gastric contents.'),
    (v_topic_id, 'Delayed Sequence Intubation (DSI) is essentially procedural sedation for the purpose of:', '["Preoxygenation in an agitated or delirious patient", "Gastric emptying in a patient with a full stomach", "C-spine clearance before laryngoscopy", "Allowing a difficult airway cart to arrive"]', 0, 'DSI uses an agent like ketamine to dissociate an agitated, combative patient who is tearing off their oxygen mask, allowing for adequate preoxygenation prior to administering a paralytic.'),
    (v_topic_id, 'During RSI, Fentanyl is sometimes given as a pretreatment agent primarily to:', '["Provide profound amnesia", "Blunt the sympathetic response (tachycardia, hypertension) to laryngoscopy", "Induce neuromuscular blockade", "Prevent fasciculations from succinylcholine"]', 1, 'Fentanyl blunts the reflex sympathetic surge caused by laryngoscopy, which is critical in patients with elevated intracranial pressure (ICP) or aortic dissection.'),
    (v_topic_id, 'Which pretreatment agent was historically used to blunt the airway reactivity and rise in intracranial pressure during intubation of a patient with a traumatic brain injury, though evidence is mixed?', '["Atropine", "Lidocaine", "Midazolam", "Dexmedetomidine"]', 1, 'Intravenous lidocaine was traditionally given 3 minutes before induction to prevent an ICP spike and suppress the cough reflex, though its modern use is debated.'),
    (v_topic_id, 'In pediatric patients under the age of 1, Atropine may be considered prior to intubation with Succinylcholine to prevent:', '["Severe bradycardia", "Malignant hyperthermia", "Hypotension", "Laryngospasm"]', 0, 'Infants have a pronounced vagal response to airway stimulation, and succinylcholine can directly cause bradycardia. Atropine (an anticholinergic) helps mitigate this.'),
    (v_topic_id, 'A patient with an anticipated difficult airway (e.g., severe Ludwig''s angina, restricted mouth opening) requires definitive airway management. The safest initial approach is:', '["RSI with Propofol and Rocuronium", "Awake fiberoptic intubation", "Blind nasotracheal intubation", "Immediate surgical cricothyrotomy without attempting medical management"]', 1, 'Awake intubation maintains the patient''s spontaneous respiratory drive and airway tone. Paralytics should be avoided in a "cannot ventilate, cannot intubate" risk scenario unless absolutely necessary.'),
    (v_topic_id, 'Nasotracheal intubation is strictly contraindicated in patients with:', '["Asthma exacerbations", "Congestive heart failure", "Apnea or midface/basilar skull fractures", "Cervical spine injuries"]', 2, 'Blind nasotracheal intubation relies on the patient''s spontaneous respirations to guide the tube ("whistle"). Midface or basilar skull fractures risk passing the tube into the cranial vault.'),
    (v_topic_id, 'When selecting an uncuffed endotracheal tube for a pediatric patient over 1 year old, which formula is used?', '["(Age in years / 4) + 4", "(Age in years / 3) + 3", "(Age in months / 2) + 2", "(Weight in kg / 2) + 4"]', 0, 'The Cole formula for uncuffed tubes is (Age/4) + 4. For cuffed tubes, it is (Age/4) + 3.5. Cuffed tubes are generally preferred in modern practice.'),
    (v_topic_id, 'To estimate the correct endotracheal tube size for a pediatric patient without a tape or formula, you can compare the tube''s outer diameter to the child''s:', '["Index finger width", "Little finger (pinky) width", "Thumb width", "Ear lobe length"]', 1, 'The width of the child''s little finger or the diameter of their nares is a traditional anatomical correlate for ETT size.'),
    (v_topic_id, 'Which of the following induction agents provides excellent analgesia and amnesia but leaves airway reflexes largely intact during procedural sedation?', '["Propofol", "Etomidate", "Ketamine", "Midazolam"]', 2, 'Ketamine produces a dissociative state characterized by profound analgesia and amnesia while typically preserving spontaneous respirations and airway protective reflexes.'),
    (v_topic_id, 'You administer Succinylcholine and notice transient muscle twitching across the patient''s chest and face. This is known as:', '["Seizures", "Myoclonus", "Fasciculations", "Tetany"]', 2, 'Succinylcholine is a depolarizing neuromuscular blocker. Its initial binding causes widespread depolarization and transient muscle contractions (fasciculations) before inducing paralysis.'),
    (v_topic_id, 'To prevent fasciculations and the subsequent rise in intragastric/intracranial pressure from Succinylcholine, one might administer a "defasciculating dose," which is:', '["10% of the paralyzing dose of a nondepolarizing agent (e.g., Rocuronium)", "50% of the standard dose of Propofol", "A full dose of Atropine", "A high dose of Fentanyl"]', 0, 'A small fraction (1/10th) of a nondepolarizing agent occupies enough receptors to prevent the visible muscle fasciculations caused by succinylcholine.'),
    (v_topic_id, 'A patient requires intubation for airway protection following a tricyclic antidepressant (TCA) overdose. They have a widened QRS and hypotension. Which induction agent should be AVOIDED if possible?', '["Ketamine", "Etomidate", "Propofol", "Succinylcholine"]', 2, 'Propofol causes significant hypotension via vasodilation and myocardial depression, which can worsen the hemodynamic instability in a TCA overdose. Etomidate or Ketamine are safer choices here.'),
    (v_topic_id, 'The optimal head positioning to align the oral, pharyngeal, and laryngeal axes for direct laryngoscopy is the:', '["Trendelenburg position", "Sniffing position (lower cervical flexion, atlanto-occipital extension)", "Reverse Trendelenburg position", "Neutral inline stabilization"]', 1, 'The "sniffing" position aligns the three airway axes, providing the most direct line of sight to the glottis.'),
    (v_topic_id, 'In an obese patient, standard supine positioning often fails to align the airway axes. The best strategy is to:', '["Ramp the patient up so the external auditory meatus aligns with the sternal notch", "Place the patient in the left lateral decubitus position", "Hyper-extend the neck as far back as possible", "Use a Miller blade exclusively"]', 0, 'Ramping elevates the head, neck, and upper torso, allowing the heavy chest to fall away from the airway and aligning the external auditory meatus with the sternal notch.'),
    (v_topic_id, 'What is the typical duration of action for a paralyzing dose of Succinylcholine?', '["1-2 minutes", "5-10 minutes", "30-45 minutes", "60-90 minutes"]', 1, 'Succinylcholine is ultra-short-acting, typically wearing off in 5 to 10 minutes, making it theoretically useful if you need the patient to rapidly recover spontaneous breathing.'),
    (v_topic_id, 'A patient with end-stage renal disease (ESRD) and a missed dialysis session requires RSI. Which paralytic is the safest choice?', '["Succinylcholine", "Rocuronium", "Vecuronium", "Pancuronium"]', 1, 'Rocuronium is a nondepolarizing agent that does not cause potassium shifts. Succinylcholine is contraindicated in hyperkalemia, which is common in ESRD patients.'),
    (v_topic_id, 'You are attempting direct laryngoscopy. The patient''s vocal cords are visualized, but they are tightly closed in spasm. The best immediate action is to:', '["Force the tube through the cords", "Wait for the paralytic to take full effect", "Administer more Etomidate", "Perform an immediate cricothyrotomy"]', 1, 'If the patient is not fully paralyzed, the vocal cords may be closed or actively moving (laryngospasm). You must wait for the onset time of the paralytic (approx. 45-60 seconds) to complete.'),
    (v_topic_id, 'Which of the following defines a "Cannot Intubate, Cannot Ventilate" (CICV) situation?', '["Failed 3 attempts at intubation but bagging maintains SpO2 at 95%", "Failed intubation, and bag-valve-mask ventilation fails to maintain oxygenation or chest rise", "Successful placement of an LMA but failed endotracheal intubation", "Inability to pass the tube beyond the teeth due to trismus"]', 1, 'CICV is a terminal airway emergency where both definitive airway placement AND rescue oxygenation (via BVM or extraglottic device) have failed. It mandates an immediate surgical airway.'),
    (v_topic_id, 'In a suspected cervical spine injury, the preferred method of airway management that minimizes spinal movement is:', '["Standard direct laryngoscopy with the sniffing position", "Manual in-line stabilization (MILS) with video laryngoscopy", "Blind nasotracheal intubation with neck extension", "Surgical cricothyrotomy as first-line"]', 1, 'MILS minimizes cervical spine motion. Video laryngoscopy requires less force and less anterior lifting than direct laryngoscopy, reducing neck movement.'),
    (v_topic_id, 'After successful intubation, what should the cuff pressure be maintained at to prevent tracheal mucosal ischemia and necrosis?', '["5-10 cm H2O", "20-30 cm H2O", "40-50 cm H2O", "Greater than 60 cm H2O"]', 1, 'Cuff pressures above 30 cm H2O exceed capillary perfusion pressure, leading to ischemia, necrosis, and subsequent tracheal stenosis.'),
    (v_topic_id, 'A patient has been intubated. Over the next 15 minutes, their blood pressure drops from 120/80 to 70/40, and airway pressures on the ventilator alarm as extremely high. What is the most life-threatening complication to suspect immediately?', '["Esophageal intubation", "Tension pneumothorax", "Anaphylaxis to Propofol", "Mainstem intubation"]', 1, 'Positive pressure ventilation in the setting of trauma or central line placement can convert a simple pneumothorax into a tension pneumothorax, causing high peak airway pressures and obstructive shock (hypotension).'),
    (v_topic_id, 'Which maneuver is specifically used to manage severe laryngospasm that does not respond to positive pressure ventilation?', '["Sellick maneuver", "Larson maneuver (Laryngospasm notch pressure)", "Heimlich maneuver", "Valsalva maneuver"]', 1, 'The Larson maneuver involves applying deep, forceful digital pressure to the laryngospasm notch (behind the earlobe, anterior to the mastoid process) while providing a jaw thrust.'),
    (v_topic_id, 'In which clinical scenario is the use of non-invasive positive pressure ventilation (NIPPV/BiPAP) contraindicated, necessitating immediate intubation?', '["COPD exacerbation with hypercapnia", "Acute cardiogenic pulmonary edema", "Altered mental status with inability to protect the airway", "Asthma exacerbation not responding to initial nebulizers"]', 2, 'NIPPV requires a cooperative, awake patient who can protect their airway. Altered mental status carries a high risk of aspiration if the patient vomits into the tight-fitting mask.'),
    (v_topic_id, 'An awake fiberoptic intubation usually requires thorough topical anesthesia of the airway. Which of the following is most commonly used for this purpose?', '["Intravenous Ketamine", "Nebulized Albuterol", "Topical 4% Lidocaine spray or atomization", "Subcutaneous Bupivacaine"]', 2, 'Topicalization of the nasopharynx, oropharynx, and larynx with local anesthetics (like Lidocaine) is critical to suppress the gag and cough reflexes during awake intubation.'),
    (v_topic_id, 'What is the primary physiological benefit of maintaining Positive End-Expiratory Pressure (PEEP) on a mechanical ventilator?', '["Decreasing intracranial pressure", "Preventing alveolar collapse at the end of expiration (atelectrauma)", "Increasing cardiac output", "Preventing ventilator-associated pneumonia"]', 1, 'PEEP splints the alveoli open, improving the surface area for gas exchange and preventing the shear stress caused by repetitive opening and closing of collapsed alveoli.'),
    (v_topic_id, 'Which ventilator mode delivers a preset tidal volume with every breath, regardless of whether it is initiated by the machine or the patient?', '["Pressure Support Ventilation (PSV)", "Synchronized Intermittent Mandatory Ventilation (SIMV)", "Assist-Control (AC) Volume Control", "Continuous Positive Airway Pressure (CPAP)"]', 2, 'In Assist-Control (AC) mode, the ventilator delivers a full, set tidal volume for every triggered breath, providing total ventilatory support.'),
    (v_topic_id, 'A patient on a ventilator has a PaO2 of 55 mmHg on an ABG. Which two ventilator settings are primarily adjusted to improve oxygenation?', '["Respiratory Rate and Tidal Volume", "FiO2 and PEEP", "I:E Ratio and Flow Rate", "Pressure Support and Trigger Sensitivity"]', 1, 'Oxygenation is governed by the fraction of inspired oxygen (FiO2) and mean airway pressure, which is primarily increased by adding Positive End-Expiratory Pressure (PEEP).'),
    (v_topic_id, 'A patient on a ventilator has a PaCO2 of 65 mmHg (hypercapnia) and a pH of 7.25. Which two ventilator settings are primarily adjusted to improve ventilation (CO2 clearance)?', '["FiO2 and PEEP", "Respiratory Rate and Tidal Volume", "I:E Ratio and Peak Flow", "Pressure Support and PEEP"]', 1, 'Ventilation (CO2 clearance) is determined by minute ventilation, which is the product of Respiratory Rate (RR) multiplied by Tidal Volume (Vt).'),
    (v_topic_id, 'You are attempting to intubate a trauma patient with massive facial smashing. You cannot visualize the vocal cords and BVM ventilation is failing. What is the definitive procedure?', '["Tracheostomy", "Needle thoracostomy", "Surgical cricothyrotomy", "Retrograde wire intubation"]', 2, 'Surgical cricothyrotomy is the definitive emergency airway in a "Cannot Intubate, Cannot Ventilate" (CICV) scenario, particularly with massive facial trauma where oral/nasal approaches are impossible.');
